const googleMark='<svg viewBox="0 0 24 24" aria-hidden="true"><path fill="#4285f4" d="M21.6 12.2c0-.7-.1-1.4-.2-2H12v3.9h5.4a4.6 4.6 0 0 1-2 3v2.5h3.3c1.9-1.8 2.9-4.3 2.9-7.4Z"/><path fill="#34a853" d="M12 22c2.7 0 5-.9 6.7-2.4l-3.3-2.5c-.9.6-2 .9-3.4.9-2.6 0-4.8-1.7-5.6-4H3v2.6A10 10 0 0 0 12 22Z"/><path fill="#fbbc05" d="M6.4 14a6 6 0 0 1 0-4V7.4H3a10 10 0 0 0 0 9.2L6.4 14Z"/><path fill="#ea4335" d="M12 6c1.5 0 2.8.5 3.8 1.5L18.7 4A9.7 9.7 0 0 0 12 2a10 10 0 0 0-9 5.4L6.4 10C7.2 7.7 9.4 6 12 6Z"/></svg>';
function socialButtonsMarkup(){return '<div class="social-signin"><div class="auth-divider"><span>অথবা চালিয়ে যান</span></div><div class="social-button-row"><button type="button" data-social="google" disabled>'+googleMark+'<span>Google</span></button><button type="button" data-social="facebook" disabled><svg class="facebook-mark" viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="11" fill="#1877f2"/><path fill="#fff" d="M13.4 22v-8.5h2.9l.4-3.3h-3.3V8.1c0-.9.3-1.6 1.7-1.6h1.8V3.6a24 24 0 0 0-2.6-.1c-2.6 0-4.4 1.6-4.4 4.5v2.2H7v3.3h2.9V22Z"/></svg><span>Facebook</span></button></div><p class="social-unavailable muted" hidden>সামাজিক লগইন এখনও চালু হয়নি।</p></div>'}
async function addSocialSignIn(register){if(register)return;const form=document.querySelector('#auth-form');if(!form)return;form.insertAdjacentHTML('afterend',socialButtonsMarkup());const wrapper=form.nextElementSibling;try{const config=await accountAPI('auth-config');wrapper.querySelectorAll('[data-social]').forEach(button=>{button.disabled=!config[button.dataset.social];button.onclick=()=>{window.location.href='/api/oauth/'+button.dataset.social+'/start'}});wrapper.querySelector('.social-unavailable').hidden=!!(config.google||config.facebook)}catch{wrapper.querySelector('.social-unavailable').hidden=false}}
function resetStepHeader(step){return '<div class="reset-intro"><span class="reset-lock">'+authIcon('lock')+'</span><h2>পাসওয়ার্ড পুনরুদ্ধার</h2><p>আপনার অ্যাকাউন্টে নিরাপদে ফিরে যান।</p><ol class="reset-steps">'+['অ্যাকাউন্ট','OTP','পাসওয়ার্ড'].map((name,index)=>'<li class="'+(index+1<=step?'current':'')+'"><span>'+(index+1)+'</span><small>'+name+'</small></li>').join('')+'</ol></div>'}
function openEmailPasswordReset(){const dialog=featureDialog(featureText('পাসওয়ার্ড উদ্ধার'),'<div id="reset-flow"></div>');dialog.classList.add('account-reset-dialog');let challenge='',resetToken='',address='',number='';const root=dialog.querySelector('#reset-flow');const showError=error=>{const box=dialog.querySelector('#reset-error');if(box)box.textContent=error.message};
 function accountStep(){challenge='';resetToken='';root.innerHTML=resetStepHeader(1)+'<form><label>প্রোফাইলের ইমেইল<input name="email" type="email" autocomplete="email" maxlength="254" value="'+esc(address)+'" placeholder="you@example.com" required></label><label>মোবাইল নম্বর<input name="phone" type="tel" autocomplete="tel" maxlength="20" value="'+esc(number)+'" placeholder="01XXXXXXXXX" required></label><p class="muted">ইমেইল ও নম্বর প্রোফাইলের সঙ্গে মিললে ইমেইলে OTP যাবে।</p><p class="danger" id="reset-error" role="alert"></p><button class="primary">OTP পাঠান</button></form>';root.querySelector('form').onsubmit=async event=>{event.preventDefault();const values=Object.fromEntries(new FormData(event.target)),button=event.target.querySelector('button');button.disabled=true;try{const result=await accountAPI('email-reset/request','POST',values);challenge=result.challenge;address=values.email;number=values.phone;otpStep()}catch(error){showError(error);button.disabled=false}}}
 function otpStep(){root.innerHTML=resetStepHeader(2)+'<form><p class="muted">তথ্য মিলে গেলে ইমেইলে ৬ সংখ্যার কোড পাঠানো হয়েছে।</p><p class="reset-address" data-user-text>'+esc(address)+'</p><label>ইমেইলের OTP<input class="otp-code" name="code" type="text" inputmode="numeric" autocomplete="one-time-code" pattern="[0-9০-৯]{6}" minlength="6" maxlength="6" placeholder="000000" required></label><p class="muted">কোডের মেয়াদ ১০ মিনিট। সর্বোচ্চ ৫ বার চেষ্টা করা যাবে।</p><p class="danger" id="reset-error" role="alert"></p><button class="primary">OTP যাচাই করুন</button><button type="button" class="reset-back">আবার শুরু করুন</button></form>';root.querySelector('.reset-back').onclick=accountStep;root.querySelector('form').onsubmit=async event=>{event.preventDefault();const button=event.target.querySelector('button');button.disabled=true;try{const result=await accountAPI('email-reset/verify','POST',{challenge,code:new FormData(event.target).get('code')});resetToken=result.token;passwordStep()}catch(error){showError(error);button.disabled=false}}}
 function passwordStep(){root.innerHTML=resetStepHeader(3)+'<form><label>নতুন পাসওয়ার্ড<input name="newPassword" type="password" autocomplete="new-password" minlength="8" maxlength="128" placeholder="কমপক্ষে ৮ অক্ষর" required></label><label>পাসওয়ার্ড নিশ্চিত করুন<input name="confirm" type="password" autocomplete="new-password" minlength="8" maxlength="128" placeholder="পাসওয়ার্ড আবার লিখুন" required></label><p class="danger" id="reset-error" role="alert"></p><button class="primary">পাসওয়ার্ড পরিবর্তন করুন</button></form>';root.querySelector('form').onsubmit=async event=>{event.preventDefault();const values=Object.fromEntries(new FormData(event.target));if(values.newPassword!==values.confirm)return showError(Error(featureText('দুটি পাসওয়ার্ড মিলছে না।')));const button=event.target.querySelector('button');button.disabled=true;try{await accountAPI('email-reset/complete','POST',{challenge,token:resetToken,newPassword:values.newPassword});challenge='';resetToken='';dialog.close();authScreen(false,featureText('পাসওয়ার্ড পরিবর্তন হয়েছে। এখন লগইন করুন।'))}catch(error){showError(error);button.disabled=false}}}
 accountStep();}
function emailProfileMarkup(){const icon=name=>typeof profileIcon==='function'?profileIcon(name):'',missing=!accountEmail;return '<div class="security-email-field"><button type="button" id="account-email-edit" class="security-email-box'+(missing?' needs-email':'')+'"><span class="profile-row-icon">'+icon('mail')+'</span><span class="security-email-copy"><strong>অ্যাকাউন্টের ইমেইল</strong>'+(accountEmail?'<small data-user-text>'+esc(accountEmail)+'</small>':'<small>ইমেইল যোগ করুন</small>')+'</span>'+(missing?'<span class="email-missing-icon" role="img" aria-label="ইমেইল যোগ করুন" title="ইমেইল যোগ করুন"><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="9"/><path d="M12 7v6M12 17h.01"/></svg></span>':icon('chevron'))+'</button>'+(accountEmail?'<small class="profile-email-status">'+(accountEmailVerified?'ইমেইল যাচাই করা হয়েছে':'ইমেইল যাচাই করা হয়নি')+'</small>':'')+'</div>'}

function openEmailSettings(){const dialog=featureDialog(featureText('অ্যাকাউন্টের ইমেইল'),'<form><label>ইমেইল<input type="email" name="email" maxlength="254" value="'+esc(accountEmail)+'" autocomplete="email" required></label><label>বর্তমান পাসওয়ার্ড<input name="password" type="password" maxlength="128" autocomplete="current-password" required></label><p class="danger" role="alert" id="email-error"></p><button class="primary">ইমেইল যাচাই করুন</button></form>');let challenge='';dialog.querySelector('form').onsubmit=async event=>{event.preventDefault();const button=event.target.querySelector('button');button.disabled=true;try{const result=await accountAPI('email/request','POST',Object.fromEntries(new FormData(event.target)));challenge=result.challenge;dialog.querySelector('section').innerHTML='<form><label>ইমেইলের OTP<input class="otp-code" name="code" type="text" inputmode="numeric" autocomplete="one-time-code" pattern="[0-9০-৯]{6}" maxlength="6" required></label><p class="danger" role="alert" id="email-error"></p><button class="primary">যাচাই করুন</button></form>';dialog.querySelector('form').onsubmit=async e=>{e.preventDefault();const submit=e.target.querySelector('button');submit.disabled=true;try{const verified=await accountAPI('email/verify','POST',{challenge,code:new FormData(e.target).get('code')});accountEmail=verified.email;accountEmailVerified=true;await rememberAccount();render()}catch(error){dialog.querySelector('#email-error').textContent=error.message;submit.disabled=false}}}catch(error){dialog.querySelector('#email-error').textContent=error.message;button.disabled=false}}}
async function checkSocialCompletion(){const params=new URLSearchParams(location.search);if(params.has('auth_error')){history.replaceState(null,'',location.pathname);authScreen(false,featureText('সামাজিক লগইন সম্পন্ন হয়নি। আবার চেষ্টা করুন।'));return}if(params.get('social')!=='complete')return;history.replaceState(null,'',location.pathname);try{const pending=await accountAPI('social/pending');const dialog=featureDialog(featureText('অ্যাকাউন্ট যুক্ত করুন'),'<p class="muted">আগের অ্যাকাউন্ট থাকলে সেই নম্বর ও পাসওয়ার্ড দিন। নতুন হলে একটি পাসওয়ার্ড বাছুন।</p><form><label>আপনার নাম<input name="name" value="'+esc(pending.name)+'" maxlength="50" required></label><label>মোবাইল নম্বর<input name="phone" type="tel" required></label><label>পাসওয়ার্ড<input name="password" type="password" minlength="8" maxlength="128" required></label><p id="social-error" class="danger" role="alert"></p><button class="primary">চালিয়ে যান</button></form>');dialog.querySelector('form').onsubmit=async event=>{event.preventDefault();const button=event.target.querySelector('button');button.disabled=true;try{await accountAPI('social/complete','POST',Object.fromEntries(new FormData(event.target)));await loadAccount()}catch(error){dialog.querySelector('#social-error').textContent=error.message;button.disabled=false}}}catch(error){alert(error.message)}}
